1	<?php
2	
3	namespace App\Filament\Pages;
4	
5	use App\Models\Activity;
6	use Carbon\Carbon;
7	use Filament\Forms\Components\Actions\Action;
8	use Filament\Forms\Components\DatePicker;
9	use Filament\Forms\Components\Select;
10	use Filament\Forms\Form;
11	use Filament\Forms\Set;
12	use Filament\Pages\Dashboard as BaseDashboard;
13	use Filament\Pages\Dashboard\Concerns\HasFiltersForm;
14	
15	/**
16	 * Dashboard con filtro per periodo, condiviso da tutti i widget.
17	 */
18	class Dashboard extends BaseDashboard
19	{
20	    use HasFiltersForm {
21	        mountHasFilters as baseMountHasFilters;
22	    }
23	
24	    /**
25	     * Livewire chiama il mount() esplicito del componente PRIMA degli hook
26	     * mount{Trait} (qui mountHasFilters, che ripristina i filtri dalla sessione/URL):
27	     * un mount() separato vedrebbe sempre $this->filters ancora vuoto e
28	     * sovrascriverebbe ogni personalizzazione ad ogni reload. Sovrascrivendo
29	     * direttamente mountHasFilters possiamo invocare prima il comportamento
30	     * originale del trait e solo dopo, se i campi risultano ancora vuoti,
31	     * applicare i default pre-calcolati (Filament applica il default di un
32	     * campo solo al primissimo fill "da zero": se la sessione contiene già
33	     * un filtro esplicito, anche vuoto, il default del campo non scatta più).
34	     */
35	    public function mountHasFilters(): void
36	    {
37	        $this->baseMountHasFilters();
38	
39	        if (filled($this->filters['startDate'] ?? null) || filled($this->filters['endDate'] ?? null)) {
40	            return;
41	        }
42	
43	        $range = $this->getUserActivitiesDateRange();
44	
45	        $this->filters['startDate'] = $range->min;
46	        $this->filters['endDate'] = $range->max;
47	
48	        $this->getFiltersForm()->fill($this->filters);
49	
50	        if ($this->persistsFiltersInSession()) {
51	            session()->put($this->getFiltersSessionKey(), $this->filters);
52	        }
53	    }
54	
55	    public function filtersForm(Form $form): Form
56	    {
57	        return $form
58	            ->schema([
59	                Select::make('preset')
60	                    ->label('Periodo rapido')
61	                    ->placeholder('Personalizzato')
62	                    ->options([
63	                        'all' => 'Tutte',
64	                        'current_week' => 'Settimana corrente',
65	                        'current_month' => 'Mese corrente',
66	                        'current_year' => 'Anno corrente',
67	                        'last_7_days' => 'Ultimi 7 giorni',
68	                        'last_30_days' => 'Ultimi 30 giorni',
69	                        'last_year' => 'Ultimo anno',
70	                    ])
71	                    ->live()
72	                    ->afterStateUpdated(function (?string $state, Set $set) {
73	                        if ($state === null) {
74	                            return;
75	                        }
76	
77	                        [$start, $end] = $this->getPresetRange($state);
78	
79	                        $set('startDate', $start);
80	                        $set('endDate', $end);
81	
82	                        // riportato a null subito dopo l'uso: se restasse valorizzato,
83	                        // riselezionare la stessa voce (es. da uno stato in sessione
84	                        // rimasto identico) non genererebbe un cambio di stato e il
85	                        // preset non verrebbe più riapplicato
86	                        $set('preset', null);
87	                    })
88	                    ->columnSpanFull(),
89	
90	                DatePicker::make('startDate')
91	                    ->label('Data inizio')
92	                    ->default(fn () => $this->getUserActivitiesDateRange()->min)
93	                    ->maxDate(fn (callable $get) => $get('endDate') ?: now())
94	                    // modifica manuale = non è più uno dei preset rapidi
95	                    ->afterStateUpdated(fn (Set $set) => $set('preset', null))
96	                    ->live(),
97	
98	                DatePicker::make('endDate')
99	                    ->label('Data fine')
100	                    ->default(fn () => $this->getUserActivitiesDateRange()->max)
101	                    ->minDate(fn (callable $get) => $get('startDate'))
102	                    ->maxDate(now())
103	                    ->afterStateUpdated(fn (Set $set) => $set('preset', null))
104	                    ->live()
105	                    ->suffixAction(
106	                        Action::make('reset')
107	                            ->label('Reimposta')
108	                            ->icon('heroicon-m-arrow-path')
109	                            ->action(function (Set $set) {
110	                                $range = $this->getUserActivitiesDateRange();
111	
112	                                $set('preset', null);
113	                                $set('startDate', Carbon::parse($range->min)->toDateString());
114	                                $set('endDate', Carbon::parse($range->max)->toDateString());
115	                            }),
116	                        isInline: true,
117	                    ),
118	            ])
119	            ->columns(2);
120	    }
121	
122	    /**
123	     * Estremi (data inizio, data fine) di un preset rapido.
124	     *
125	     * @return array{0: string, 1: string}
126	     */
127	    protected function getPresetRange(string $preset): array
128	    {
129	        $now = Carbon::now();
130	
131	        return match ($preset) {
132	            'all' => [
133	                Carbon::parse($this->getUserActivitiesDateRange()->min)->toDateString(),
134	                Carbon::parse($this->getUserActivitiesDateRange()->max)->toDateString(),
135	            ],
136	            // la settimana comincia di domenica
137	            'current_week' => [
138	                $now->copy()->startOfWeek(Carbon::SUNDAY)->toDateString(),
139	                $now->copy()->startOfWeek(Carbon::SUNDAY)->addDays(6)->toDateString(),
140	            ],
141	            'current_month' => [
142	                $now->copy()->startOfMonth()->toDateString(),
143	                $now->copy()->endOfMonth()->toDateString(),
144	            ],
145	            'current_year' => [
146	                $now->copy()->startOfYear()->toDateString(),
147	                $now->copy()->endOfYear()->toDateString(),
148	            ],
149	            'last_7_days' => [
150	                $now->copy()->subDays(6)->toDateString(),
151	                $now->toDateString(),
152	            ],
153	            'last_30_days' => [
154	                $now->copy()->subDays(29)->toDateString(),
155	                $now->toDateString(),
156	            ],
157	            'last_year' => [
158	                $now->copy()->subYear()->addDay()->toDateString(),
159	                $now->toDateString(),
160	            ],
161	        };
162	    }
163	
164	    /**
165	     * Data della prima e dell'ultima attività registrata dall'utente,
166	     * usate come estremi preimpostati del filtro periodo.
167	     */
168	    protected function getUserActivitiesDateRange(): object
169	    {
170	        return once(fn () => Activity::query()
171	            ->where('user_id', auth()->id())
172	            ->selectRaw('min(start_date_local) as min, max(start_date_local) as max')
173	            ->first());
174	    }
175	}
