1	<?php
2	
3	namespace App\Filament\Widgets;
4	
5	use App\Enums\ActivityType;
6	use App\Models\Activity;
7	use Filament\Support\Colors\Color;
8	use Filament\Support\RawJs;
9	use Filament\Widgets\ChartWidget;
10	use Filament\Widgets\Concerns\InteractsWithPageFilters;
11	use Illuminate\Database\Eloquent\Builder;
12	use Illuminate\Support\Collection;
13	
14	/**
15	 * Conteggio numerico e ripartizione percentuale delle attività per tipo,
16	 * filtrata per il periodo selezionato in dashboard.
17	 *
18	 * Colori ed etichette arrivano da ActivityType, la stessa fonte
19	 * usata dal badge "Tipo" nella tabella attività, per restare coerenti
20	 * in tutto il pannello.
21	 */
22	class ActivityTypesChartWidget extends ChartWidget
23	{
24	    use InteractsWithPageFilters;
25	
26	    protected static ?string $heading = 'Numero attività per tipo';
27	
28	    protected static ?int $sort = 0;
29	
30	    protected static ?string $maxHeight = '320px';
31	
32	    /**
33	     * Oltre le fette più grandi il resto viene accorpato in "Altro",
34	     * altrimenti una torta con troppe fette diventa illeggibile.
35	     */
36	    private const MAX_SLICES = 7;
37	
38	    protected function getType(): string
39	    {
40	        return 'pie';
41	    }
42	
43	    protected function getData(): array
44	    {
45	        $slices = $this->getSlices();
46	
47	        if ($slices->isEmpty()) {
48	            return [
49	                'datasets' => [['data' => []]],
50	                'labels' => [],
51	            ];
52	        }
53	
54	        return [
55	            'datasets' => [
56	                [
57	                    'label' => 'Attività',
58	                    'data' => $slices->pluck('total')->all(),
59	                    'backgroundColor' => $slices->pluck('color')->all(),
60	                    // bordo trasparente = 2px di superficie fra le fette, in entrambi i temi
61	                    'borderColor' => 'transparent',
62	                    'borderWidth' => 2,
63	                ],
64	            ],
65	            'labels' => $slices->pluck('label')->all(),
66	        ];
67	    }
68	
69	    protected function getOptions(): RawJs
70	    {
71	        return RawJs::make(<<<'JS'
72	            {
73	                plugins: {
74	                    legend: {
75	                        position: 'right',
76	                        labels: {
77	                            boxWidth: 12,
78	                            boxHeight: 12,
79	                            usePointStyle: true,
80	                            pointStyle: 'circle',
81	                            // conteggio già visibile in legenda, senza dover passare il mouse
82	                            generateLabels: (chart) => {
83	                                const { labels, datasets } = chart.data;
84	
85	                                return labels.map((label, i) => ({
86	                                    text: `${label}: ${datasets[0].data[i]}`,
87	                                    fillStyle: datasets[0].backgroundColor[i],
88	                                    strokeStyle: datasets[0].backgroundColor[i],
89	                                    pointStyle: 'circle',
90	                                    index: i,
91	                                }));
92	                            },
93	                        },
94	                    },
95	                    tooltip: {
96	                        callbacks: {
97	                            label: (context) => {
98	                                const total = context.dataset.data.reduce((sum, value) => sum + value, 0);
99	                                const percentage = total ? (context.parsed / total * 100) : 0;
100	
101	                                return ` ${context.label}: ${context.parsed} (${percentage.toFixed(1)}%)`;
102	                            },
103	                        },
104	                    },
105	                },
106	            }
107	        JS);
108	    }
109	
110	    /**
111	     * Una riga per fetta: totale, etichetta e colore risolti da ActivityType.
112	     * Oltre MAX_SLICES le code vengono accorpate in "Altro".
113	     *
114	     * @return Collection<int, array{total: int, label: string, color: string}>
115	     */
116	    private function getSlices(): Collection
117	    {
118	        $counts = Activity::query()
119	            ->where('user_id', auth()->id())
120	            ->when(
121	                $this->filters['startDate'] ?? null,
122	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '>=', $date)
123	            )
124	            ->when(
125	                $this->filters['endDate'] ?? null,
126	                fn (Builder $query, $date) => $query->whereDate('start_date_local', '<=', $date)
127	            )
128	            ->selectRaw('type, COUNT(*) as total')
129	            ->groupBy('type')
130	            ->pluck('total', 'type')
131	            ->sortDesc();
132	
133	        $slices = $counts->map(function (int $total, ?string $type) {
134	            $activityType = $type !== null ? ActivityType::tryFrom($type) : null;
135	
136	            return [
137	                'total' => $total,
138	                'label' => $activityType?->getLabel() ?? 'Sconosciuto',
139	                'color' => $this->colorToRgb($activityType?->getColor() ?? Color::Gray),
140	            ];
141	        })->values();
142	
143	        if ($slices->count() <= self::MAX_SLICES) {
144	            return $slices;
145	        }
146	
147	        return $slices
148	            ->take(self::MAX_SLICES)
149	            ->push([
150	                'total' => $slices->slice(self::MAX_SLICES)->sum('total'),
151	                'label' => 'Altro',
152	                'color' => $this->colorToRgb(Color::Gray),
153	            ]);
154	    }
155	
156	    /**
157	     * @param  array<int, string>  $color
158	     */
159	    private function colorToRgb(array $color): string
160	    {
161	        return "rgb({$color[500]})";
162	    }
163	}
